// GENERATED by `npm run sync:edge` from src/game — do not edit.
export const MAX_LEVEL = 30;

/** XP needed to go from level n to level n+1: round(100 × n^1.5). */
export function xpToNextLevel(level: number): number {
  return Math.round(100 * Math.pow(level, 1.5));
}

/** Total XP needed to reach `level` from level 1. */
export function totalXpForLevel(level: number): number {
  let total = 0;
  for (let n = 1; n < Math.min(level, MAX_LEVEL); n++) total += xpToNextLevel(n);
  return total;
}

export interface LevelInfo {
  level: number;
  /** XP accumulated inside the current level. */
  xpIntoLevel: number;
  /** XP needed to finish the current level (0 at max level). */
  xpForNext: number;
  /** 0..1 */
  progress: number;
}

export function levelFromXp(xp: number): LevelInfo {
  let level = 1;
  let remaining = Math.max(0, Math.floor(xp));
  while (level < MAX_LEVEL) {
    const need = xpToNextLevel(level);
    if (remaining < need) {
      return { level, xpIntoLevel: remaining, xpForNext: need, progress: remaining / need };
    }
    remaining -= need;
    level += 1;
  }
  return { level: MAX_LEVEL, xpIntoLevel: remaining, xpForNext: 0, progress: 1 };
}
